-- Australia Animal Science Technician profile.
-- No exact current OSCA Animal Science Technician title exists.
-- Closest non-clinical technical scope: OSCA 311132 Animal Husbandry Technician; current ANZSCO counterpart 311113.
-- Veterinary Technologist 269532 is clinical/diagnostic and is intentionally kept separate.

update public.courses_au set official_course_url='https://study.csu.edu.au/courses/bachelor-animal-science',official_url_status='verified',official_url_checked_at=now(),official_url_source='Charles Sturt current course page, verified 2026-08-09' where institution_id='charles-sturt-university' and course_code='068972G';
update public.courses_au set official_course_url='https://study.uq.edu.au/study-options/programs/bachelor-veterinary-technology-2387',official_url_status='verified',official_url_checked_at=now(),official_url_source='UQ current international course page, verified 2026-08-09' where institution_id='the-university-of-queensland' and course_code='087886D';

insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at)
values ('AU:animal-science-technician','AU','animal-science-technician','Animal Science Technician (Animal Husbandry Technician proxy)','OSCA','2024 v1.0','3111','AUD',false,'VETASSESS assesses related ANZSCO 311113 Animal Husbandry Technician; procedure-specific licensing may apply','https://www.vetassess.com.au/check-my-occupation/professional-occupations/animal-husbandry-technician','profile_ready','2026-08-09',now())
